INSERT INTO `email_templates` (`id`, `title`, `slug`, `content`, `button_text`, `button_url`, `deleted_at`, `created_at`, `updated_at`) VALUES
(1, '{\"en\":\"New Ride Request Available!\",\"ar\":\"\\u0637\\u0644\\u0628 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f \\u0645\\u062a\\u0627\\u062d!\",\"fr\":\"Nouvelle demande de trajet disponible !\",\"es\":\"\\u00a1Nueva solicitud de viaje disponible!\"}', 'ride-request-driver', '{\"en\":\"<p>Hello {{driver_name}},<\\/p>\\r\\n<p>There is a new ride request available for you from <strong>{{rider_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Service:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Vehicle:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Distance:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Fare:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Pick up &amp; Drop off Locations:<\\/strong><br \\/>{{locations}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Hurry up and accept the request before it expires!<\\/p>\\r\\n<p>Drive safe,<br \\/>{{Your Company Name}}<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{driver_name}}\\u060c<\\/p>\\r\\n<p>\\u064a\\u0648\\u062c\\u062f \\u0637\\u0644\\u0628 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f \\u0645\\u062a\\u0627\\u062d \\u0644\\u0643 \\u0645\\u0646 <strong>{{rider_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-right: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u062e\\u062f\\u0645\\u0629:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0631\\u0643\\u0628\\u0629:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0623\\u062c\\u0631\\u0629:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0644\\u0627\\u0645 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0635\\u064a\\u0644:<\\/strong><br \\/>{{locations}}<\\/p>\\r\\n<\\/div>\\r\\n<p>\\u0633\\u0627\\u0631\\u0639 \\u0628\\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0642\\u0628\\u0644 \\u0627\\u0646\\u062a\\u0647\\u0627\\u0621 \\u0635\\u0644\\u0627\\u062d\\u064a\\u062a\\u0647!<\\/p>\\r\\n<p>\\u0642\\u062f \\u0628\\u0623\\u0645\\u0627\\u0646\\u060c<br \\/>{{Your Company Name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{driver_name}},<\\/p>\\r\\n<p>Une nouvelle demande de trajet est disponible pour vous de la part de <strong>{{rider_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Service:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>V&eacute;hicule:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Distance:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Tarif:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Lieux de prise en charge et de d&eacute;pose:<\\/strong><br \\/>{{locations}}<\\/p>\\r\\n<\\/div>\\r\\n<p>D&eacute;p&ecirc;chez-vous d\'accepter la demande avant qu\'elle n\'expire !<\\/p>\\r\\n<p>Roulez prudemment,<br \\/>{{Your Company Name}}<\\/p>\",\"es\":\"<p>Hola {{driver_name}},<\\/p>\\r\\n<p>Hay una nueva solicitud de viaje disponible para ti de parte de <strong>{{rider_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Servicio:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Veh&iacute;culo:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Distancia:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Tarifa:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Lugares de recogida y entrega:<\\/strong><br \\/>{{locations}}<\\/p>\\r\\n<\\/div>\\r\\n<p>&iexcl;Date prisa y acepta la solicitud antes de que expire!<\\/p>\\r\\n<p>Conduce con cuidado,<br \\/>{{Your Company Name}}<\\/p>\"}', NULL, NULL, NULL, '2025-01-24 04:18:01', '2025-12-26 06:20:28'),
(2, '{\"en\":\"New Ride Created\",\"ar\":\"\\u062a\\u0645 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629\",\"fr\":\"Nouveau trajet cr\\u00e9\\u00e9\",\"es\":\"Nuevo viaje creado\"}', 'create-ride-admin', '{\"en\":\"<p>Hello Admin,<\\/p>\\r\\n<p>A new ride has been created in the system. Details are as follows:<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Ride Number:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Rider:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Driver:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Service:<\\/strong> {{services}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Fare:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Log in to the admin panel for more details.<\\/p>\\r\\n<p>System Notification,<br \\/>{{Your Company Name}}<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b \\u0645\\u062f\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645\\u060c<\\/p>\\r\\n<p>\\u062a\\u0645 \\u0625\\u0646\\u0634\\u0627\\u0621 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645. \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0643\\u0627\\u0644\\u062a\\u0627\\u0644\\u064a:<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-right: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0631\\u0627\\u0643\\u0628:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0633\\u0627\\u0626\\u0642:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u062e\\u062f\\u0645\\u0629:<\\/strong> {{services}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0623\\u062c\\u0631\\u0629:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>\\u0642\\u0645 \\u0628\\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0644\\u0648\\u062d\\u0629 \\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u0629 \\u0644\\u0645\\u0632\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644.<\\/p>\\r\\n<p>\\u0625\\u0634\\u0639\\u0627\\u0631 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645\\u060c<br \\/>{{Your Company Name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour Admin,<\\/p>\\r\\n<p>Un nouveau trajet a &eacute;t&eacute; cr&eacute;&eacute; dans le syst&egrave;me. Les d&eacute;tails sont les suivants :<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Num&eacute;ro de trajet:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Passager:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Conducteur:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Service:<\\/strong> {{services}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Tarif:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Connectez-vous au panneau d\'administration pour plus de d&eacute;tails.<\\/p>\\r\\n<p>Notification syst&egrave;me,<br \\/>{{Your Company Name}}<\\/p>\",\"es\":\"<p>Hola Admin,<\\/p>\\r\\n<p>Se ha creado un nuevo viaje en el sistema. Los detalles son los siguientes:<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>N&uacute;mero de viaje:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Pasajero:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Conductor:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Servicio:<\\/strong> {{services}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Tarifa:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Inicie sesi&oacute;n en el panel de administraci&oacute;n para m&aacute;s detalles.<\\/p>\\r\\n<p>Notificaci&oacute;n del sistema,<br \\/>{{Your Company Name}}<\\/p>\"}', NULL, NULL, NULL, '2025-01-24 04:24:31', '2025-12-26 06:19:37'),
(3, '{\"en\":\"Update on Your Bid for a Ride\",\"ar\":\"\\u062a\\u062d\\u062f\\u064a\\u062b \\u0628\\u0634\\u0623\\u0646 \\u0639\\u0631\\u0636\\u0643 \\u0644\\u0644\\u0631\\u062d\\u0644\\u0629\",\"fr\":\"Mise \\u00e0 jour de votre offre pour un trajet\",\"es\":\"Actualizaci\\u00f3n de su oferta para un viaje\"}', 'bid-status-driver', '{\"en\":\"<p>Hello {{driver_name}},<\\/p>\\r\\n<p>Your bid for a ride with <strong>{{rider_name}}<\\/strong> has been updated.<\\/p>\\r\\n<div style=\\\"background: #f7fafc; padding: 15px; border-radius: 4px; border-left: 4px solid #4a5568; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Rider:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Bid Status:<\\/strong> <strong style=\\\"color: #2d3748; text-transform: uppercase;\\\">{{bid_status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>If your bid was accepted, please proceed to the app to start the journey.<\\/p>\\r\\n<p>Happy driving,<br \\/>{{Your Company Name}}<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{driver_name}}\\u060c<\\/p>\\r\\n<p>\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062b \\u0639\\u0631\\u0636\\u0643 \\u0644\\u0644\\u0631\\u0643\\u0648\\u0628 \\u0645\\u0639 <strong>{{rider_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #f7fafc; padding: 15px; border-radius: 4px; border-right: 4px solid #4a5568; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0631\\u0627\\u0643\\u0628:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u0639\\u0631\\u0636:<\\/strong> <strong style=\\\"color: #2d3748; text-transform: uppercase;\\\">{{bid_status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>\\u0625\\u0630\\u0627 \\u062a\\u0645 \\u0642\\u0628\\u0648\\u0644 \\u0639\\u0631\\u0636\\u0643\\u060c \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0625\\u0644\\u0649 \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0644\\u0628\\u062f\\u0621 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629.<\\/p>\\r\\n<p>\\u0642\\u064a\\u0627\\u062f\\u0629 \\u0633\\u0639\\u064a\\u062f\\u0629\\u060c<br \\/>{{Your Company Name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{driver_name}},<\\/p>\\r\\n<p>Votre offre pour un trajet avec <strong>{{rider_name}}<\\/strong> a &eacute;t&eacute; mise &agrave; jour.<\\/p>\\r\\n<div style=\\\"background: #f7fafc; padding: 15px; border-radius: 4px; border-left: 4px solid #4a5568; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Passager:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Statut de l\'offre:<\\/strong> <strong style=\\\"color: #2d3748; text-transform: uppercase;\\\">{{bid_status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>Si votre offre a &eacute;t&eacute; accept&eacute;e, veuillez vous rendre sur l\'application pour commencer le voyage.<\\/p>\\r\\n<p>Bonne route,<br \\/>{{Your Company Name}}<\\/p>\",\"es\":\"<p>Hola {{driver_name}},<\\/p>\\r\\n<p>Tu oferta para un viaje con <strong>{{rider_name}}<\\/strong> ha sido actualizada.<\\/p>\\r\\n<div style=\\\"background: #f7fafc; padding: 15px; border-radius: 4px; border-left: 4px solid #4a5568; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Pasajero:<\\/strong> {{rider_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Estado de la oferta:<\\/strong> <strong style=\\\"color: #2d3748; text-transform: uppercase;\\\">{{bid_status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>Si se acept&oacute; su oferta, proceda a la aplicaci&oacute;n para iniciar el viaje.<\\/p>\\r\\n<p>Feliz viaje,<br \\/>{{Your Company Name}}<\\/p>\"}', NULL, NULL, NULL, '2025-01-24 04:35:35', '2025-12-26 06:23:40'),
(4, '{\"en\":\"New Withdrawal Request\",\"ar\":\"\\u0637\\u0644\\u0628 \\u0633\\u062d\\u0628 \\u062c\\u062f\\u064a\\u062f\",\"fr\":\"Nouvelle demande de retrait\",\"es\":\"Nueva solicitud de retiro\"}', 'create-withdraw-request-admin', '{\"en\":\"<p>Hello Admin,<\\/p>\\r\\n<p>A new withdrawal request has been submitted by <strong>{{driver_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fff5f5; padding: 15px; border-radius: 4px; border-left: 4px solid #e53e3e; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Driver Name:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Withdrawal Amount:<\\/strong> {{amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Please review the request and take necessary action from the admin dashboard.<\\/p>\\r\\n<p>Regards,<br \\/>{{Your Company Name}} FinOps<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b \\u0645\\u062f\\u064a\\u0631 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645\\u060c<\\/p>\\r\\n<p>\\u062a\\u0645 \\u062a\\u0642\\u062f\\u064a\\u0645 \\u0637\\u0644\\u0628 \\u0633\\u062d\\u0628 \\u062c\\u062f\\u064a\\u062f \\u0628\\u0648\\u0627\\u0633\\u0637\\u0629 <strong>{{driver_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fff5f5; padding: 15px; border-radius: 4px; border-right: 4px solid #e53e3e; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0633\\u0645 \\u0627\\u0644\\u0633\\u0627\\u0626\\u0642:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0633\\u062d\\u0628:<\\/strong> {{amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>\\u064a\\u0631\\u062c\\u0649 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u0627\\u0644\\u0637\\u0644\\u0628 \\u0648\\u0627\\u062a\\u062e\\u0627\\u0630 \\u0627\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u0644\\u0627\\u0632\\u0645 \\u0645\\u0646 \\u0644\\u0648\\u062d\\u0629 \\u062a\\u062d\\u0643\\u0645 \\u0627\\u0644\\u0625\\u062f\\u0627\\u0631\\u0629.<\\/p>\\r\\n<p>\\u0645\\u0639 \\u0627\\u0644\\u062a\\u062d\\u064a\\u0629\\u060c<br \\/>{{Your Company Name}} FinOps<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour Admin,<\\/p>\\r\\n<p>Une nouvelle demande de retrait a &eacute;t&eacute; soumise par <strong>{{driver_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fff5f5; padding: 15px; border-radius: 4px; border-left: 4px solid #e53e3e; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Nom du conducteur:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Montant du retrait:<\\/strong> {{amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Veuillez examiner la demande et prendre les mesures n&eacute;cessaires depuis le tableau de bord d\'administration.<\\/p>\\r\\n<p>Cordialement,<br \\/>{{Your Company Name}} FinOps<\\/p>\",\"es\":\"<p>Hola Admin,<\\/p>\\r\\n<p>Se ha enviado una nueva solicitud de retiro por parte de <strong>{{driver_name}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fff5f5; padding: 15px; border-radius: 4px; border-left: 4px solid #e53e3e; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Nombre del conductor:<\\/strong> {{driver_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Monto del retiro:<\\/strong> {{amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Por favor, revise la solicitud y tome las medidas necesarias desde el panel de administraci&oacute;n.<\\/p>\\r\\n<p>Saludos,<br \\/>{{Your Company Name}} FinOps<\\/p>\"}', NULL, NULL, NULL, '2025-01-24 04:40:23', '2025-12-26 06:21:25'),
(5, '{\"en\":\"Withdraw Request Status Updated\",\"ar\":\"\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062b \\u062d\\u0627\\u0644\\u0629 \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643\",\"fr\":\"Le statut de votre demande de retrait a \\u00e9t\\u00e9 mis \\u00e0 jour\",\"es\":\"Se ha actualizado el estado de su solicitud de retiro\"}', 'update-withdraw-request-driver', '{\"en\":\"<p>Hello {{driver_name}},<\\/p>\\r\\n<p>Your withdrawal request for <strong>{{amount}}<\\/strong> has been updated.<\\/p>\\r\\n<div style=\\\"background: #ebf8ff; padding: 15px; border-radius: 4px; border-left: 4px solid #3182ce; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Requested Amount:<\\/strong> {{amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Current Status:<\\/strong> <span style=\\\"background: #3182ce; color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 14px; font-weight: bold; text-transform: uppercase;\\\">{{status}}<\\/span><\\/p>\\r\\n<\\/div>\\r\\n<p>If you have any questions, please contact our support team.<\\/p>\\r\\n<p>Best regards,<br \\/>{{Your Company Name}} Support Team<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{driver_name}}\\u060c<\\/p>\\r\\n<p>\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062b \\u0637\\u0644\\u0628 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0627\\u0644\\u062e\\u0627\\u0635 \\u0628\\u0643 \\u0628\\u0642\\u064a\\u0645\\u0629 <strong>{{amount}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #ebf8ff; padding: 15px; border-radius: 4px; border-right: 4px solid #3182ce; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0637\\u0644\\u0648\\u0628:<\\/strong> {{amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u062d\\u0627\\u0644\\u064a\\u0629:<\\/strong> <span style=\\\"background: #3182ce; color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 14px; font-weight: bold; text-transform: uppercase;\\\">{{status}}<\\/span><\\/p>\\r\\n<\\/div>\\r\\n<p>\\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646 \\u0644\\u062f\\u064a\\u0643 \\u0623\\u064a \\u0623\\u0633\\u0626\\u0644\\u0629\\u060c \\u064a\\u0631\\u062c\\u0649 \\u0627\\u0644\\u0627\\u062a\\u0635\\u0627\\u0644 \\u0628\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0644\\u062f\\u064a\\u0646\\u0627.<\\/p>\\r\\n<p>\\u0623\\u0637\\u064a\\u0628 \\u0627\\u0644\\u062a\\u062d\\u064a\\u0627\\u062a\\u060c<br \\/>\\u0641\\u0631\\u064a\\u0642 \\u062f\\u0639\\u0645 {{Your Company Name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{driver_name}},<\\/p>\\r\\n<p>Votre demande de retrait de <strong>{{amount}}<\\/strong> a &eacute;t&eacute; mise &agrave; jour.<\\/p>\\r\\n<div style=\\\"background: #ebf8ff; padding: 15px; border-radius: 4px; border-left: 4px solid #3182ce; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Montant demand&eacute;:<\\/strong> {{amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Statut actuel:<\\/strong> <span style=\\\"background: #3182ce; color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 14px; font-weight: bold; text-transform: uppercase;\\\">{{status}}<\\/span><\\/p>\\r\\n<\\/div>\\r\\n<p>Si vous avez des questions, veuillez contacter notre &eacute;quipe d\'assistance.<\\/p>\\r\\n<p>Cordialement,<br \\/>L\'&eacute;quipe d\'assistance {{Your Company Name}}<\\/p>\",\"es\":\"<p>Hola {{driver_name}},<\\/p>\\r\\n<p>Su solicitud de retiro por <strong>{{amount}}<\\/strong> ha sido actualizada.<\\/p>\\r\\n<div style=\\\"background: #ebf8ff; padding: 15px; border-radius: 4px; border-left: 4px solid #3182ce; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Monto solicitado:<\\/strong> {{amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Estado actual:<\\/strong> <span style=\\\"background: #3182ce; color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 14px; font-weight: bold; text-transform: uppercase;\\\">{{status}}<\\/span><\\/p>\\r\\n<\\/div>\\r\\n<p>Si tiene alguna pregunta, p&oacute;ngase en contacto con nuestro equipo de soporte.<\\/p>\\r\\n<p>Saludos cordiales,<br \\/>El equipo de soporte de {{Your Company Name}}<\\/p>\"}', NULL, NULL, NULL, '2025-01-24 04:45:26', '2025-12-26 06:22:25'),
(6, '{\"en\":\"New Ride Assigned\",\"ar\":\"\\u062a\\u0645 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629\",\"fr\":\"Nouveau trajet assign\\u00e9\",\"es\":\"Nuevo viaje asignado\"}', 'create-ride-driver', '{\"en\":\"<p>Hello {{driver_name}},<\\/p>\\r\\n<p>A new ride has been assigned to you. Here are the ride details:<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Ride Number:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Rider:<\\/strong> {{rider_name}} ({{rider_phone}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Service:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Vehicle:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Fare:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Distance:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Please open the app to view full details and proceed with the ride.<\\/p>\\r\\n<p>Best regards,<br \\/>{{Your Company Name}} Team<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{driver_name}}\\u060c<\\/p>\\r\\n<p>\\u062a\\u0645 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u0644\\u0643. \\u0625\\u0644\\u064a\\u0643 \\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629:<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-right: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0631\\u0642\\u0645 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0631\\u0627\\u0643\\u0628:<\\/strong> {{rider_name}} ({{rider_phone}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u062e\\u062f\\u0645\\u0629:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0631\\u0643\\u0628\\u0629:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0623\\u062c\\u0631\\u0629:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<\\/div>\\r\\n<p>\\u064a\\u0631\\u062c\\u0649 \\u0641\\u062a\\u062d \\u0627\\u0644\\u062a\\u0637\\u0628\\u064a\\u0642 \\u0644\\u0639\\u0631\\u0636 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0648\\u0627\\u0644\\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0641\\u064a \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629.<\\/p>\\r\\n<p>\\u0623\\u0637\\u064a\\u0628 \\u0627\\u0644\\u062a\\u062d\\u064a\\u0627\\u062a\\u060c<br \\/>\\u0641\\u0631\\u064a\\u0642 {{Your Company Name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{driver_name}},<\\/p>\\r\\n<p>Un nouveau trajet vous a &eacute;t&eacute; attribu&eacute;. Voici les d&eacute;tails du trajet :<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Num&eacute;ro de trajet:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Passager:<\\/strong> {{rider_name}} ({{rider_phone}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Service:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>V&eacute;hicule:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Tarif:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Distance:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Veuillez ouvrir l\'application pour voir tous les d&eacute;tails et proc&eacute;der au trajet.<\\/p>\\r\\n<p>Cordialement,<br \\/>L\'&eacute;quipe {{Your Company Name}}<\\/p>\",\"es\":\"<p>Hola {{driver_name}},<\\/p>\\r\\n<p>Se te ha asignado un nuevo viaje. Aqu&iacute; est&aacute;n los detalles del viaje:<\\/p>\\r\\n<div style=\\\"background: #f4f4f4; padding: 15px; border-radius: 4px; border-left: 4px solid #000; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>N&uacute;mero de viaje:<\\/strong> #{{ride_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Pasajero:<\\/strong> {{rider_name}} ({{rider_phone}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Servicio:<\\/strong> {{services}} ({{service_category}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Veh&iacute;culo:<\\/strong> {{vehicle_type}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Tarifa:<\\/strong> {{fare_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Distancia:<\\/strong> {{distance}} {{distance_unit}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Por favor, abre la aplicaci&oacute;n para ver los detalles completos y proceder con el viaje.<\\/p>\\r\\n<p>Saludos cordiales,<br \\/>El equipo de {{Your Company Name}}<\\/p>\"}', NULL, NULL, NULL, '2025-12-26 06:10:11', '2025-12-26 06:17:49'),
(7, '{\"en\":\"Driver Document Verification Update\",\"ar\":\"\\u062a\\u062d\\u062f\\u064a\\u062b \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0648\\u062b\\u064a\\u0642\\u0629 \\u0627\\u0644\\u0633\\u0627\\u0626\\u0642\",\"fr\":\"Mise \\u00e0 jour de la v\\u00e9rification du document du conducteur\",\"es\":\"Actualizaci\\u00f3n de la verificaci\\u00f3n del documento del conductor\"}', 'driver-document-status-update', '{\"en\":\"<p>Hello {{driver_name}},<\\/p>\\r\\n<p>Your document verification process has been updated.<\\/p>\\r\\n<div style=\\\"background: #f9fafb; padding: 15px; border-radius: 4px; border-left: 4px solid #a0aec0; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Document Name:<\\/strong> {{document_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Verification Status:<\\/strong> <strong style=\\\"text-transform: uppercase;\\\">{{status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>Please log in to your profile to view more details or upload a new document if needed.<\\/p>\\r\\n<p>Best regards,<br \\/>{{Your Company Name}} Compliance Team<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{driver_name}}\\u060c<\\/p>\\r\\n<p>\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062b \\u0639\\u0645\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642 \\u0645\\u0646 \\u0648\\u062b\\u0627\\u0626\\u0642\\u0643.<\\/p>\\r\\n<div style=\\\"background: #f9fafb; padding: 15px; border-radius: 4px; border-right: 4px solid #a0aec0; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0633\\u0645 \\u0627\\u0644\\u0648\\u062b\\u064a\\u0642\\u0629:<\\/strong> {{document_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u062d\\u0627\\u0644\\u0629 \\u0627\\u0644\\u062a\\u062d\\u0642\\u0642:<\\/strong> <strong style=\\\"text-transform: uppercase;\\\">{{status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>\\u064a\\u0631\\u062c\\u0649 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0625\\u0644\\u0649 \\u0645\\u0644\\u0641\\u0643 \\u0627\\u0644\\u0634\\u062e\\u0635\\u064a \\u0644\\u0639\\u0631\\u0636 \\u0627\\u0644\\u0645\\u0632\\u064a\\u062f \\u0645\\u0646 \\u0627\\u0644\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0623\\u0648 \\u062a\\u062d\\u0645\\u064a\\u0644 \\u0648\\u062b\\u064a\\u0642\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u0625\\u0630\\u0627 \\u0644\\u0632\\u0645 \\u0627\\u0644\\u0623\\u0645\\u0631.<\\/p>\\r\\n<p>\\u0623\\u0637\\u064a\\u0628 \\u0627\\u0644\\u062a\\u062d\\u064a\\u0627\\u062a\\u060c<br \\/>\\u0641\\u0631\\u064a\\u0642 \\u0627\\u0644\\u0627\\u0645\\u062a\\u062b\\u0627\\u0644 \\u0641\\u064a {{Your Company Name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{driver_name}},<\\/p>\\r\\n<p>Votre processus de v&eacute;rification de documents a &eacute;t&eacute; mis &agrave; jour.<\\/p>\\r\\n<div style=\\\"background: #f9fafb; padding: 15px; border-radius: 4px; border-left: 4px solid #a0aec0; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Nom du document:<\\/strong> {{document_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Statut de v&eacute;rification:<\\/strong> <strong style=\\\"text-transform: uppercase;\\\">{{status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>Veuillez vous connecter &agrave; votre profil pour voir plus de d&eacute;tails ou t&eacute;l&eacute;charger un nouveau document si n&eacute;cessaire.<\\/p>\\r\\n<p>Cordialement,<br \\/>L\'&eacute;quipe de conformit&eacute; {{Your Company Name}}<\\/p>\",\"es\":\"<p>Hola {{driver_name}},<\\/p>\\r\\n<p>Su proceso de verificaci&oacute;n de documentos ha sido actualizado.<\\/p>\\r\\n<div style=\\\"background: #f9fafb; padding: 15px; border-radius: 4px; border-left: 4px solid #a0aec0; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Nombre del documento:<\\/strong> {{document_name}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Estado de verificaci&oacute;n:<\\/strong> <strong style=\\\"text-transform: uppercase;\\\">{{status}}<\\/strong><\\/p>\\r\\n<\\/div>\\r\\n<p>Inicie sesi&oacute;n en su perfil para ver m&aacute;s detalles o cargar un nuevo documento si es necesario.<\\/p>\\r\\n<p>Saludos cordiales,<br \\/>El equipo de cumplimiento de {{Your Company Name}}<\\/p>\"}', NULL, NULL, NULL, '2025-12-26 06:15:04', '2025-12-26 06:24:23'),
(8, '{\"en\":\"You\'ve Earned a Referral Bonus!\",\"ar\":\"\\u0644\\u0642\\u062f \\u0631\\u0628\\u062d\\u062a \\u0645\\u0643\\u0627\\u0641\\u0623\\u0629 \\u0625\\u062d\\u0627\\u0644\\u0629!\",\"fr\":\"Vous avez gagn\\u00e9 un bonus de parrainage !\",\"es\":\"\\u00a1Has ganado un bono de referido!\"}', 'referral-bonus-credited', '{\"en\":\"<p>Hello {{referrer_name}},<\\/p>\\r\\n<p>Congratulations! You have earned a referral bonus for referring <strong>{{referred_name}}<\\/strong> ({{referred_type}}).<\\/p>\\r\\n<div style=\\\"background: #f0fff4; padding: 15px; border-radius: 4px; border-left: 4px solid #38a169; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Bonus Amount:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Referral Details:<\\/strong> {{referred_name}} ({{referred_type}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Ride Amount:<\\/strong> {{ride_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>The bonus has been credited to your wallet. Thank you for helping {{company_name}} grow!<\\/p>\\r\\n<p>Cheers,<br \\/>{{company_name}} Team<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{referrer_name}}\\u060c<\\/p>\\r\\n<p>\\u062a\\u0647\\u0627\\u0646\\u064a\\u0646\\u0627! \\u0644\\u0642\\u062f \\u062d\\u0635\\u0644\\u062a \\u0639\\u0644\\u0649 \\u0645\\u0643\\u0627\\u0641\\u0623\\u0629 \\u0625\\u062d\\u0627\\u0644\\u0629 \\u0644\\u0625\\u062d\\u0627\\u0644\\u0629 <strong>{{referred_name}}<\\/strong> ({{referred_type}}).<\\/p>\\r\\n<div style=\\\"background: #f0fff4; padding: 15px; border-radius: 4px; border-right: 4px solid #38a169; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0645\\u0643\\u0627\\u0641\\u0623\\u0629:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u062a\\u0641\\u0627\\u0635\\u064a\\u0644 \\u0627\\u0644\\u0625\\u062d\\u0627\\u0644\\u0629:<\\/strong> {{referred_name}} ({{referred_type}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0645\\u0628\\u0644\\u063a \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629:<\\/strong> {{ride_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>\\u062a\\u0645 \\u0625\\u064a\\u062f\\u0627\\u0639 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0641\\u0623\\u0629 \\u0641\\u064a \\u0645\\u062d\\u0641\\u0638\\u062a\\u0643. \\u0634\\u0643\\u0631\\u0627\\u064b \\u0644\\u0645\\u0633\\u0627\\u0639\\u062f\\u062a\\u0643 \\u0641\\u064a \\u0646\\u0645\\u0648 {{company_name}}!<\\/p>\\r\\n<p>\\u062a\\u062d\\u064a\\u0627\\u062a\\u0646\\u0627\\u060c<br \\/>\\u0641\\u0631\\u064a\\u0642 {{company_name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{referrer_name}},<\\/p>\\r\\n<p>F&eacute;licitations ! Vous avez gagn&eacute; un bonus de parrainage pour avoir parrain&eacute; <strong>{{referred_name}}<\\/strong> ({{referred_type}}).<\\/p>\\r\\n<div style=\\\"background: #f0fff4; padding: 15px; border-radius: 4px; border-left: 4px solid #38a169; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Montant du bonus:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>D&eacute;tails du parrainage:<\\/strong> {{referred_name}} ({{referred_type}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Montant du trajet:<\\/strong> {{ride_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Le bonus a &eacute;t&eacute; cr&eacute;dit&eacute; sur votre portefeuille. Merci d\'aider {{company_name}} &agrave; grandir !<\\/p>\\r\\n<p>Sant&eacute;,<br \\/>L\'&eacute;quipe {{company_name}}<\\/p>\",\"es\":\"<p>Hola {{referrer_name}},<\\/p>\\r\\n<p>&iexcl;Felicitaciones! Has ganado un bono de referido por recomendar a <strong>{{referred_name}}<\\/strong> ({{referred_type}}).<\\/p>\\r\\n<div style=\\\"background: #f0fff4; padding: 15px; border-radius: 4px; border-left: 4px solid #38a169; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Monto del bono:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Detalles del referido:<\\/strong> {{referred_name}} ({{referred_type}})<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Monto del viaje:<\\/strong> {{ride_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>El bono ha sido acreditado en su billetera. &iexcl;Gracias por ayudar a {{company_name}} a crecer!<\\/p>\\r\\n<p>Saludos,<br \\/>El equipo de {{company_name}}<\\/p>\"}', NULL, NULL, NULL, '2025-12-26 06:15:35', '2025-12-26 06:25:06'),
(9, '{\"en\":\"Congratulations! You\'ve Completed Incentive Level\",\"ar\":\"\\u062a\\u0647\\u0627\\u0646\\u064a\\u0646\\u0627! \\u0644\\u0642\\u062f \\u0623\\u0643\\u0645\\u0644\\u062a \\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0641\\u0623\\u0629\",\"fr\":\"F\\u00e9licitations ! Vous avez termin\\u00e9 le niveau d\'incitation\",\"es\":\"\\u00a1Felicitaciones! Has completado el nivel de incentivo\"}', 'driver-incentive-level-completed', '{\"en\":\"<p>Hello {{driver_name}},<\\/p>\\r\\n<p>Amazing job! You have successfully completed <strong>Incentive Level {{level_number}}<\\/strong> for the <strong>{{period_type}}<\\/strong> period.<\\/p>\\r\\n<div style=\\\"background: #fffaf0; padding: 15px; border-radius: 4px; border-left: 4px solid #dd6b20; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Level Achieved:<\\/strong> Level {{level_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Target Rides Met:<\\/strong> {{target_rides}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Bonus Earned:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Keep up the great work and continue reaching new milestones with {{company_name}}!<\\/p>\\r\\n<p>Drive more, earn more!<br \\/>{{company_name}} Team<\\/p>\",\"ar\":\"<div dir=\\\"rtl\\\" style=\\\"text-align: right;\\\">\\r\\n<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{driver_name}}\\u060c<\\/p>\\r\\n<p>\\u0639\\u0645\\u0644 \\u0631\\u0627\\u0626\\u0639! \\u0644\\u0642\\u062f \\u0623\\u0643\\u0645\\u0644\\u062a \\u0628\\u0646\\u062c\\u0627\\u062d <strong>\\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0645\\u0643\\u0627\\u0641\\u0623\\u0629 {{level_number}}<\\/strong> \\u0644\\u0641\\u062a\\u0631\\u0629 <strong>{{period_type}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fffaf0; padding: 15px; border-radius: 4px; border-right: 4px solid #dd6b20; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0645\\u062d\\u0642\\u0642:<\\/strong> \\u0627\\u0644\\u0645\\u0633\\u062a\\u0648\\u0649 {{level_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0631\\u062d\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0633\\u062a\\u0647\\u062f\\u0641\\u0629 \\u0627\\u0644\\u0645\\u062d\\u0642\\u0642\\u0629:<\\/strong> {{target_rides}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>\\u0627\\u0644\\u0645\\u0643\\u0627\\u0641\\u0623\\u0629 \\u0627\\u0644\\u0645\\u0643\\u062a\\u0633\\u0628\\u0629:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>\\u0627\\u0633\\u062a\\u0645\\u0631 \\u0641\\u064a \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0631\\u0627\\u0626\\u0639 \\u0648\\u0648\\u0627\\u0635\\u0644 \\u062a\\u062d\\u0642\\u064a\\u0642 \\u0645\\u0639\\u0627\\u0644\\u0645 \\u062c\\u062f\\u064a\\u062f\\u0629 \\u0645\\u0639 {{company_name}}!<\\/p>\\r\\n<p>\\u0642\\u062f \\u0623\\u0643\\u062b\\u0631\\u060c \\u062a\\u0631\\u0628\\u062d \\u0623\\u0643\\u062b\\u0631!<br \\/>\\u0641\\u0631\\u064a\\u0642 {{company_name}}<\\/p>\\r\\n<\\/div>\",\"fr\":\"<p>Bonjour {{driver_name}},<\\/p>\\r\\n<p>Un travail incroyable ! Vous avez termin&eacute; avec succ&egrave;s le <strong>niveau d\'incitation {{level_number}}<\\/strong> pour la p&eacute;riode <strong>{{period_type}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fffaf0; padding: 15px; border-radius: 4px; border-left: 4px solid #dd6b20; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Niveau atteint:<\\/strong> Niveau {{level_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Objectif de trajets atteint:<\\/strong> {{target_rides}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Bonus gagn&eacute;:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>Continuez votre excellent travail et continuez &agrave; atteindre de nouveaux sommets avec {{company_name}} !<\\/p>\\r\\n<p>Conduisez plus, gagnez plus !<br \\/>L\'&eacute;quipe {{company_name}}<\\/p>\",\"es\":\"<p>Hola {{driver_name}},<\\/p>\\r\\n<p>&iexcl;Incre&iacute;ble trabajo! Ha completado con &eacute;xito el <strong>nivel de incentivo {{level_number}}<\\/strong> para el per&iacute;odo <strong>{{period_type}}<\\/strong>.<\\/p>\\r\\n<div style=\\\"background: #fffaf0; padding: 15px; border-radius: 4px; border-left: 4px solid #dd6b20; margin: 20px 0;\\\">\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Nivel alcanzado:<\\/strong> Nivel {{level_number}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Viajes objetivo cumplidos:<\\/strong> {{target_rides}}<\\/p>\\r\\n<p style=\\\"margin: 5px 0;\\\"><strong>Bono ganado:<\\/strong> {{bonus_amount}}<\\/p>\\r\\n<\\/div>\\r\\n<p>&iexcl;Siga con el gran trabajo y contin&uacute;e alcanzando nuevos hitos con {{company_name}}!<\\/p>\\r\\n<p>&iexcl;Conduce m&aacute;s, gana m&aacute;s!<br \\/>El equipo de {{company_name}}<\\/p>\"}', NULL, NULL, NULL, '2025-12-26 06:15:58', '2025-12-26 06:27:15');

