INSERT INTO `onboardings` (`id`, `title`, `type`, `description`, `onboarding_image_id`, `status`, `created_by_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '{\"en\":\"Start Driving\",\"ar\":\"ابدأ القيادة\",\"fr\":\"Commencez à conduire\",\"de\":\"Einen Job annehmen\",\"es\":\"Commencez à conduire\"}', 'driver', '{\"en\":\"Begin accepting ride requests and grow your daily earnings.\",\"ar\":\"ابدأ بقبول طلبات الركوب وقم بزيادة أرباحك اليومية.\",\"fr\":\"Commencez à accepter les demandes de courses et augmentez vos revenus quotidiens.\",\"de\":\"Durchsuchen und akzeptieren Sie Jobanfragen ganz einfach mit nur einem Tippen. Behalten Sie die Kontrolle über Ihren Zeitplan und beginnen Sie sofort zu verdienen.\",\"es\":\"Commencez à accepter les demandes de courses et augmentez vos revenus quotidiens.\"}', '{\"en\":\"1056\",\"es\":\"1056\",\"fr\":\"1056\",\"ar\":\"1056\"}', 1, 1, '2025-03-16 18:20:42', '2025-12-26 06:35:17', NULL),
(2, '{\"en\":\"Complete Trips\",\"ar\":\"العنوان: رحلات مكتملة\",\"fr\":\"Courses Complétées\",\"de\":\"Geld verdienen\",\"es\":\"Viajes Completados\"}', 'driver', '{\"en\":\"Finish rides successfully to boost your overall income.\",\"ar\":\"الوصف: أتمم رحلاتك بنجاح لتعزيز إجمالي دخلك.\",\"fr\":\"Terminez vos courses avec succès pour augmenter vos revenus globaux.\",\"de\":\"Absolvieren Sie Fahrten oder Lieferungen und verdienen Sie nahtlos Geld. Lassen Sie sich schnell bezahlen und genießen Sie finanzielle Freiheit après vos propres conditions.\",\"es\":\"Finaliza tus viajes exitosamente para aumentar tus ingresos totales.\"}', '{\"en\":\"1058\",\"es\":\"1058\",\"fr\":\"1058\",\"ar\":\"1058\"}', 1, 1, '2025-03-16 18:20:42', '2025-12-26 06:37:11', NULL),
(3, '{\"en\":\"Get Paid Instantly\",\"ar\":\"العنوان: الدفع الفوري\",\"fr\":\"Paiement Instantané\",\"de\":\"Aktivieren Sie Ihren Standort\",\"es\":\"Pago Instantáneo\"}', 'driver', '{\"en\":\"Receive your earnings directly after every completed trip.\",\"ar\":\"الوصف: استلم أجرك مباشرة بعد كل رحلة تكتمل.\",\"fr\":\"Recevez vos gains directement après chaque course effectuée.\",\"de\":\"Aktivieren Sie Ihre Standortdienste, um nahegelegene Jobanfragen zu erhalten und Kunden in Echtzeit einen besseren Service zu bieten.\",\"es\":\"Recibe tus ganancias directamente después de cada viaje completado.\"}', '{\"en\":\"1060\",\"es\":\"1060\",\"fr\":\"1060\",\"ar\":\"1060\"}', 1, 1, '2025-03-16 18:20:42', '2025-12-26 06:38:29', NULL),
(4, '{\"en\":\"Choose. Tap. Go!\",\"ar\":\"العنوان: اختر. انقر. انطلق!\",\"fr\":\"Choisissez. Appuyez. Partez!\",\"de\":\"Wählen Sie Ihr Ziel\",\"es\":\"Elige. Toca. ¡Ve!\"}', 'rider', '{\"en\":\"Enter your destination and we’ll find the nearest driver for you in moments!\",\"ar\":\"الوصف: أدخل وجهتك وسنجد لك أقرب سائق في لحظات!\",\"fr\":\"Entrez votre destination et nous vous trouvons le conducteur le plus proche en un instant !\",\"de\":\"Wählen Sie Ihre bevorzugte Route oder Ihr Ziel, bevor Sie Ihre Fahrt beginnen. Planen Sie Ihre Fahrten für eine reibungslose und stressfreie Reise.\",\"es\":\"¡Ingresa tu destino y te encontraremos al conductor más cercano en momentos!\"}', '{\"en\":\"1062\",\"es\":\"1062\",\"fr\":\"1062\",\"ar\":\"1062\"}', 1, 1, '2025-03-16 18:20:42', '2025-12-26 06:41:38', NULL),
(5, '{\"en\":\"Know the Fare, Then Go\",\"ar\":\"العنوان: اعرف الأجرة ثم انطلق\",\"fr\":\"Connaissez le Prix, puis Part\",\"de\":\"Genießen Sie Ihre Reise\",\"es\":\"Conoce la Tarifa, Luego Ve\"}', 'rider', '{\"en\":\"Check your fare upfront and start your trip with no surprises.\",\"ar\":\"الوصف: تحقق من أجرتك مقدّماً وابدأ رحلتك دون مفاجآت.\",\"fr\":\"Vérifiez votre tarif à l\'avance et commencez votre course sans mauvaises surprises.\",\"de\":\"Lehnen Sie sich zurück und genießen Sie eine komfortable Fahrt mit unserem nahtlosen Service. Reisen Sie entspannt und erreichen Sie Ihr Ziel sorgenfrei.\",\"es\":\"Consulta tu tarifa por adelantado y comienza tu viaje sin sorpresas.\"}', '{\"en\":\"1064\",\"es\":\"1064\",\"fr\":\"1064\",\"ar\":\"1064\"}', 1, 1, '2025-03-16 18:20:42', '2025-12-26 06:43:45', NULL),
(6, '{\"en\":\"Ride in Comfort\",\"ar\":\"العنوان: اركب براحة\",\"fr\":\"Voyagez Confortablement\",\"de\":\"Tarif prüfen & Fahrt buchen\",\"es\":\"Viaja con Comodidad\"}', 'rider', '{\"en\":\"Enjoy smooth, safe, and reliable rides with drivers you can trust.\",\"ar\":\"الوصف: استمتع برحلات سلسة وآمنة وموثوقة مع سائقين يمكنك الوثوق بهم.\",\"fr\":\"Profitez de trajets fluides, sûrs et fiables avec des conducteurs de confiance.\",\"de\":\"Erhalten Sie einen geschätzten Fahrpreis, bevor Sie Ihre Fahrt bestätigen. Vergleichen Sie Optionen und buchen Sie Ihre Reise mit Vertrauen.\",\"es\":\"Disfruta de viajes suaves, seguros y confiables con conductores en los que puedes confiar.\"}', '{\"en\":\"1066\",\"es\":\"1066\",\"fr\":\"1066\",\"ar\":\"1066\"}', 1, 1, '2025-03-16 18:20:42', '2025-12-26 06:45:55', NULL);

