INSERT INTO `plans` (`id`, `name`, `duration`, `description`, `price`, `status`, `created_by_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '{\"en\": \"Standard Ride Plan\", \"fr\": \"Plan de trajet standard\", \"de\": \"Standard-Fahrplan\", \"ar\": \"خطة رحلة عادية\"}', 'monthly', '{\"en\": [\"Affordable city travel for short distances.\", \"Comfortable ride within the city limits.\"], \"fr\": [\"Voyage urbain abordable pour de courtes distances.\", \"Trajet confortable dans les limites de la ville.\"], \"de\": [\"Erschwingliche Stadtfahrten für kurze Strecken.\", \"Komfortable Fahrt innerhalb der Stadtgrenzen.\"], \"ar\": [\"سفر ميسور التكلفة داخل المدينة للمسافات القصيرة.\", \"رحلة مريحة داخل حدود المدينة.\"]}', '150.00', 1, 1, '2025-01-23 05:20:17', '2025-01-23 05:29:01', NULL),
(2, '{\"en\": \"Intercity Ride Plan\", \"fr\": \"Plan de trajet interurbain\", \"de\": \"Stadtübergreifender Fahrplan\", \"ar\": \"خطة رحلة بين المدن\"}', 'yearly', '{\"en\": [\"Travel between cities with door-to-door service.\", \"Comfort and reliability for long-distance journeys.\", \"Fixed pricing for intercity travel.\"], \"fr\": [\"Voyage entre les villes avec service porte-à-porte.\", \"Confort et fiabilité pour les longs trajets.\", \"Tarification fixe pour les voyages interurbains.\"], \"de\": [\"Reisen zwischen Städten mit Tür-zu-Tür-Service.\", \"Komfort und Zuverlässigkeit für Langstreckenfahrten.\", \"Feste Preise für stadtübergreifende Fahrten.\"], \"ar\": [\"السفر بين المدن مع خدمة من الباب إلى الباب.\", \"الراحة والموثوقية للرحلات طويلة المسافة.\", \"تسعير ثابت للسفر بين المدن.\"]}', '5500.00', 1, 1, '2025-01-23 05:23:12', '2025-01-23 05:30:06', NULL),
(3, '{\"en\": \"Premium Ride Plan\", \"fr\": \"Plan de trajet premium\", \"de\": \"Premium-Fahrplan\", \"ar\": \"خطة رحلة مميزة\"}', 'monthly', '{\"en\": [\"Luxury ride with premium comfort and amenities.\", \"Indulge in top-tier service with every ride.\"], \"fr\": [\"Trajet de luxe avec confort et équipements premium.\", \"Profitez dun service de premier ordre à chaque trajet.\"], \"de\": [\"Luxusfahrt mit Premium-Komfort und Annehmlichkeiten.\", \"Genießen Sie erstklassigen Service bei jeder Fahrt.\"], \"ar\": [\"رحلة فاخرة مع راحة ووسائل رفاهية متميزة.\", \"استمتع بخدمة من الطراز الأول مع كل رحلة.\"]}', '600.00', 1, 1, '2025-01-23 05:31:03', '2025-01-23 05:31:03', NULL),
(4, '{\"en\":\"Weekend Package Plan\", \"fr\": \"Plan forfait week-end\", \"de\": \"Wochenendpaketplan\", \"ar\": \"خطة حزمة عطلة نهاية الأسبوع\"}', 'yearly', '{\"en\": [\"Round-trip intercity ride for a weekend getaway.\", \"Flexible departure and return time for your convenience.\", \"Explore new destinations with ease and comfort.\"], \"fr\": [\"Trajet interurbain aller-retour pour un week-end dévasion.\", \"Heure de départ et de retour flexibles pour votre commodité.\", \"Explorez de nouvelles destinations en toute simplicité et confort.\"], \"de\": [\"Hin- und Rückfahrt zwischen Städten für ein Wochenendausflug.\", \"Flexible Abfahrts- und Rückkehrzeiten für Ihren Komfort.\", \"Erkunden Sie neue Ziele mit Leichtigkeit und Komfort.\"], \"ar\": [\"رحلة ذهاب وعودة بين المدن لعطلة نهاية الأسبوع.\", \"وقت مغادرة وعودة مرن لراحتك.\", \"استكشف الوجهات الجديدة بسهولة وراحة.\"]}', '9000.00', 1, 1, '2025-01-23 05:31:56', '2025-01-23 05:31:56', NULL),
(5, '{\"en\": \"Rental Plan\", \"fr\": \"Plan de location\", \"de\": \"Mietplan\", \"ar\": \"خطة إيجار\"}', 'monthly', '{\"en\": [\"Rent a car for up to 8 hours with unlimited mileage.\", \"Flexible rental for personal use.\", \"Ideal for day trips or city exploration.\"], \"fr\": [\"Louez une voiture jusquà 8 heures avec kilométrage illimité.\", \"Location flexible pour un usage personnel.\", \"Idéal pour des excursions dune journée ou lexploration de la ville.\"], \"de\": [\"Mieten Sie ein Auto für bis zu 8 Stunden mit unbegrenzter Kilometerleistung.\", \"Flexible Vermietung für den persönlichen Gebrauch.\", \"Ideal für Tagesausflüge oder Stadterkundung.\"], \"ar\": [\"استأجر سيارة لمدة تصل إلى 8 ساعات مع مسافة غير محدودة.\", \"إيجار مرن للاستخدام الشخصي.\", \"مثالي للرحلات اليومية أو استكشاف المدينة.\"]}', '1000.00', 1, 1, '2025-01-23 05:32:53', '2025-01-23 05:32:53', NULL),
(6, '{\"en\": \"Scheduled Ride Plan\", \"fr\": \"Plan de trajet programmé\", \"de\": \"Geplanter Fahrplan\", \"ar\": \"خطة رحلة مجدولة\"}', 'monthly', '{\"en\": [\"Pre-book your ride for a specific time slot.\", \"Guaranteed availability when you need it most.\"], \"fr\": [\"Réservez votre trajet à lavance pour un créneau horaire spécifique.\", \"Disponibilité garantie quand vous en avez le plus besoin.\"], \"de\": [\"Buchen Sie Ihre Fahrt im Voraus für einen bestimmten Zeitraum.\", \"Garantierte Verfügbarkeit, wenn Sie sie am dringendsten benötigen.\"], \"ar\": [\"احجز رحلتك مسبقًا لفترة زمنية محددة.\", \"توفر مضمون عندما تحتاجه بشدة.\"]}', '250.00', 1, 1, '2025-01-23 05:33:34', '2025-01-23 05:33:34', NULL),
(7, '{\"en\": \"Package Ride Plan\", \"fr\": \"Plan de trajet colis\", \"de\": \"Paket-Fahrplan\", \"ar\": \"خطة رحلة الطرود\"}', 'monthly', '{\"en\": [\"Fast delivery of small packages within the city.\", \"Secure transport for parcels to any location.\"], \"fr\": [\"Livraison rapide de petits colis dans la ville.\", \"Transport sécurisé des colis vers nimporte quel endroit.\"], \"de\": [\"Schnelle Lieferung kleiner Pakete innerhalb der Stadt.\", \"Sicherer Transport von Paketen an jeden Ort.\"], \"ar\": [\"توصيل سريع للطرود الصغيرة داخل المدينة.\", \"نقل آمن للطرود إلى أي موقع.\"]}', '120.00', 1, 1, '2025-01-23 05:34:52', '2025-01-23 05:34:52', NULL);

