(1, '{\"en\":\"New Ride Assignment\",\"ar\":\"\\u062a\\u0645 \\u062a\\u0639\\u064a\\u064a\\u0646 \\u0631\\u062d\\u0644\\u0629 \\u062c\\u062f\\u064a\\u062f\\u0629\",\"fr\":\"Nouvelle course assign\",\"es\":null}', 'create-ride-driver', '{\"en\":\"{{driver_name}}, youve been assigned Ride #{{ride_number}} ({{service_category}}). Pick up {{rider_name}} for a {{distance}}{{distance_unit}} trip. Fare: {{fare_amount}}\",\"ar\":null,\"fr\":\"{{driver_name}}, on vous a assign\\u00c3\\u00a9 la course #{{ride_number}} ({{service_category}}). Allez chercher {{rider_name}} pour un trajet de {{distance}}{{distance_unit}}. Tarif : {{fare_amount}}\",\"es\":null}', '{\"en\":\"https:\\/\\/google.com\",\"ar\":\"https:\\/\\/google.com\",\"fr\":\"https:\\/\\/google.com\",\"es\":null}', NULL, '2025-06-01 13:38:04', '2025-12-26 06:29:43'),
