(1, '{\"en\": \"Cab\", \"ar\": \"سيارة أجرة\", \"fr\": \"Taxi\", \"de\": \"Taxi\"}', 'cab', '{\"en\": \"Quick and reliable ride service.\", \"ar\": \"خدمة رحلات سريعة وموثوقة.\", \"fr\": \"Service de transport rapide et fiable.\", \"de\": \"Schneller und zuverlässiger Fahrdienst.\"}', 1364, 1276, 'cab', 1, 1, 1, '2025-04-23 19:50:10', '2026-01-03 01:27:50', NULL),
(2, '{\"en\": \"Parcel\", \"fr\": \"Colis\", \"de\": \"Paket\", \"ar\": \"طرد\"}', 'parcel', '{\"en\": \"Secure and fast deliveries.\", \"ar\": \"توصيلات آمنة وسريعة.\", \"fr\": \"Livraisons sécurisées et rapides.\", \"de\": \"Sichere und schnelle Lieferungen.\"}', 1028, 1280, 'parcel', 1, 0, 1, '2025-04-23 19:50:10', '2025-12-26 05:57:13', NULL),
(3, '{\"en\": \"Freight\", \"fr\": \"Fret\", \"de\": \"Fracht\", \"ar\": \"شحن\"}', 'freight', '{\"en\": \"Efficient and reliable goods transport.\", \"ar\": \"نقل بضائع فعال وموثوق.\", \"fr\": \"Transport de marchandises efficace et fiable.\", \"de\": \"Effizienter und zuverlässiger Warentransport.\"}', 1366, 1278, 'freight', 1, 0, 1, '2025-04-23 19:50:10', '2026-01-03 01:27:58', NULL),
(4, '{\"en\": \"Ambulance\", \"fr\": \"Ambulance\", \"de\": \"Krankenwagen\", \"ar\": \"سيارة إسعاف\"}', 'ambulance', '{\"en\": \"Emergency medical transport.\", \"ar\": \"نقل طبي طارئ.\", \"fr\": \"Transport medical durgence.\", \"de\": \"Notfallmedizinischer Transport.\"}', 1032, 1270, 'ambulance', 1, 0, 1, '2025-04-23 14:20:10', '2025-12-26 05:56:22', NULL);

