INSERT INTO `service_categories` (`id`, `name`, `slug`, `type`, `service_id`, `description`, `service_category_image_id`, `status`, `created_by_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '{\"en\":\"Ride\",\"fr\":\"Trajet\",\"de\":\"Fahrt\",\"ar\":\"رحلة\"}', 'ride', 'ride', '1', '{\"en\":\"Long-distance travel options connecting cities, ideal for both passengers and freight shipments.\",\"ar\":\"خيارات السفر لمسافات طويلة تربط بين المدن، مثالية لكل من الركاب وشحنات البضائع.\",\"fr\":\"Options de voyage longue distance reliant les villes, idéales pour les passagers et les expéditions de fret.\",\"de\":\"Langstreckenreiseoptionen, die Städte verbinden, ideal für Passagiere und Frachttransporte.\"}', 962, 1, 1, '2025-03-31 19:55:23', '2025-12-25 08:54:20', NULL),
(2, '{\"en\":\"Intercity\",\"fr\":\"Interurbain\",\"de\":\"Stadtübergreifend\",\"ar\":\"بين المدن\"}', 'intercity', 'intercity', '1', '{\"en\":\"For smooth and reliable intercity travel\",\"ar\":\"للسفر السلس والموثوق بين المدن\",\"fr\":\"Pour des déplacements interurbains fluides et fiables\",\"de\":\"Für reibungslose und zuverlässige Überlandfahrten\"}', 970, 1, 1, '2025-03-31 19:55:23', '2025-12-02 06:53:23', NULL),
(3, '{\"en\":\"Package\",\"fr\":\"Colis\",\"de\":\"Paket\",\"ar\":\"طرد\"}', 'package', 'package', '1', '{\"en\":\"Package delivery services for both small and large parcels, ensuring timely and secure transport.\",\"ar\":\"خدمات توصيل الطرود للطرود الصغيرة والكبيرة، مع ضمان النقل الآمن وفي الوقت المحدد.\",\"fr\":\"Services de livraison de colis pour les petits et grands paquets, assurant un transport ponctuel et sécurisé.\",\"de\":\"Paketzustelldienste für kleine und große Pakete, die einen pünktlichen und sicheren Transport gewährleisten.\"}', 976, 1, 1, '2025-03-31 19:55:23', '2025-12-03 00:37:35', NULL),
(4, '{\"en\":\"Schedule\",\"fr\":\"Programme\",\"de\":\"Zeitplan\",\"ar\":\"جدول\"}', 'schedule', 'schedule', '1', '{\"en\":\"Scheduled transport services for planned trips, offering both passenger and freight options.\",\"ar\":\"خدمات النقل المجدولة للرحلات المخطط لها، تقدم خيارات لكل من الركاب والبضائع.\",\"fr\":\"Services de transport programmés pour les voyages planifiés, offrant des options pour les passagers et le fret.\",\"de\":\"Geplante Transportdienste für geplante Reisen, die sowohl Passagier- als auch Frachtoptionen bieten.\"}', 966, 1, 1, '2025-03-31 19:55:23', '2025-12-03 00:38:11', NULL),
(5, '{\"en\":\"Rental\",\"fr\":\"Location\",\"de\":\"Miete\",\"ar\":\"إيجار\"}', 'rental', 'rental', '1', '{\"en\":\"Vehicle rentals for short or long-term use, suitable for personal or business requirements.\",\"ar\":\"تأجير مركبات للاستخدام قصير أو طويل الأجل، مناسبة للاحتياجات الشخصية أو التجارية.\",\"fr\":\"Location de véhicules pour une utilisation à court ou long terme, adaptée aux besoins personnels ou professionnels.\",\"de\":\"Fahrzeugvermietung für kurzfristige oder langfristige Nutzung, geeignet für private oder geschäftliche Anforderungen.\"}', 964, 1, 1, '2025-03-31 19:55:23', '2025-12-03 00:38:22', NULL),
(6, '{\"en\":\"Ride\",\"fr\":\"Trajet\",\"de\":\"Fahrt\",\"ar\":\"رحلة\"}', 'ride-parcel', 'ride', '2', '{\"en\":\"Express parcel delivery services for time-sensitive packages across cities.\",\"ar\":\"خدمات توصيل الطرود السريعة للشحنات الحساسة للوقت بين المدن.\",\"fr\":\"Services de livraison de colis express pour les envois urgents entre les villes.\",\"de\":\"Express-Paketzustelldienste für zeitkritische Sendungen zwischen Städten.\"}', 994, 1, 1, '2025-03-31 19:55:23', '2025-12-03 00:50:21', NULL),
(7, '{\"en\":\"Intercity\",\"fr\":\"Interurbain\",\"de\":\"Stadtübergreifend\",\"ar\":\"بين المدن\"}', 'intercity-parcel', 'intercity', '2', '{\"en\":\"Reliable parcel delivery between cities with guaranteed delivery times.\",\"ar\":\"توصيل طرود موثوق بين المدن مع أوقات تسليم مضمونة.\",\"fr\":\"Livraison de colis fiable entre les villes avec des délais de livraison garantis.\",\"de\":\"Zuverlässige Paketzustellung zwischen Städten mit garantierten Lieferzeiten.\"}', 996, 1, 1, '2025-03-31 19:55:23', '2025-12-03 00:51:04', NULL),
(8, '{\"en\":\"Schedule\",\"fr\":\"Programme\",\"de\":\"Zeitplan\",\"ar\":\"جدول\"}', 'schedule-parcel', 'schedule', '2', '{\"en\":\"Pre-scheduled parcel pickup and delivery services for planned shipments.\",\"ar\":\"خدمات استلام وتسليم الطرود المجدولة مسبقاً للشحنات المخطط لها.\",\"fr\":\"Services de ramassage et de livraison de colis pré-programmés pour les expéditions planifiées.\",\"de\":\"Vorgeplante Paketabhol- und Zustelldienste für geplante Sendungen.\"}', 998, 1, 1, '2025-03-31 19:55:23', '2025-12-03 00:52:17', NULL),
(9, '{\"en\":\"Ride\",\"fr\":\"Trajet\",\"de\":\"Fahrt\",\"ar\":\"رحلة\"}', 'ride-freight', 'ride', '3', '{\"en\":\"Heavy freight transport services for commercial goods and large shipments.\",\"ar\":\"خدمات نقل البضائع الثقيلة للبضائع التجارية والشحنات الكبيرة.\",\"fr\":\"Services de transport de fret lourd pour les marchandises commerciales et les expéditions volumineuses.\",\"de\":\"Schwerfrachttransportdienste für gewerbliche Waren und große Sendungen.\"}', 1014, 1, 1, '2025-03-31 19:55:23', '2025-12-03 01:07:50', NULL),
(10, '{\"en\":\"Intercity\",\"fr\":\"Interurbain\",\"de\":\"Stadtübergreifend\",\"ar\":\"بين المدن\"}', 'intercity-freight', 'intercity', '3', '{\"en\":\"Intercity freight services for business logistics and supply chain needs.\",\"ar\":\"خدمات الشحن بين المدن لاحتياجات لوجستيات الأعمال وسلسلة التوريد.\",\"fr\":\"Services de fret interurbains pour les besoins logistiques et de chaîne dapprovisionnement des entreprises.\",\"de\":\"Überlandfrachtdienste für Geschäftslogistik- und Lieferkettenanforderungen.\"}', 1016, 1, 1, '2025-03-31 19:55:23', '2025-12-03 01:08:18', NULL),
(11, '{\"en\":\"Schedule\",\"fr\":\"Programme\",\"de\":\"Zeitplan\",\"ar\":\"جدول\"}', 'schedule-freight', 'schedule', '3', '{\"en\":\"Scheduled freight services with fixed routes and delivery timelines.\",\"ar\":\"خدمات الشحن المجدولة مع مسارات ثابتة وجداول زمنية للتسليم.\",\"fr\":\"Services de fret programmés avec des itinéraires fixes et des délais de livraison.\",\"de\":\"Geplante Frachtdienste mit festen Routen und Lieferzeitplänen.\"}', 1012, 1, 1, '2025-03-31 19:55:23', '2025-12-03 01:08:28', NULL);

