INSERT INTO `sms_templates` (`id`, `title`, `slug`, `content`, `url`, `deleted_at`, `created_at`, `updated_at`) VALUES
(2, '{\"en\":\"New Ride Created\",\"fr\":\"Nouvelle course créée\",\"de\":\"Neue Fahrt erstellt\",\"ar\":\"تم إنشاء رحلة جديدة\"}', 'create-ride-admin', '{\"en\":\"Hello {{rider_name}}, your ride #{{ride_number}} with driver {{driver_name}} for {{service_category}} service has been created. Estimated fare: {{fare_amount}} for {{distance}}{{distance_unit}}.\",\"fr\":\"Bonjour {{rider_name}}, votre course #{{ride_number}} avec le chauffeur {{driver_name}} pour le service {{service_category}} a été créée. Tarif estimé : {{fare_amount}} pour {{distance}}{{distance_unit}}.\",\"de\":\"Hallo {{rider_name}}, Ihre Fahrt #{{ride_number}} mit Fahrer {{driver_name}} für den Service {{service_category}} wurde erstellt. Geschätzter Fahrpreis: {{fare_amount}} für {{distance}}{{distance_unit}}.\",\"ar\":\"مرحباً {{rider_name}}، تم إنشاء رحلتك رقم #{{ride_number}} مع السائق {{driver_name}} لخدمة {{service_category}}. الأجرة المقدرة: {{fare_amount}} مقابل {{distance}}{{distance_unit}}.\"}', '{\"en\":\"/ride/{{ride_id}}\",\"fr\":\"/ride/{{ride_id}}\",\"de\":\"/ride/{{ride_id}}\",\"ar\":\"/ride/{{ride_id}}\"}', NULL, '2025-06-01 12:32:50', '2025-06-01 12:32:50'),
(3, '{\"en\":\"New Ride Assignment\",\"fr\":\"Nouvelle course assignée\",\"de\":\"Neue Fahrtzuweisung\",\"ar\":\"مهنة رحلة جديدة\"}', 'create-ride-driver', '{\"en\":\"Hi {{driver_name}}, you have been assigned Ride #{{ride_number}}. Pick up {{rider_name}} ({{rider_phone}}) for {{service_category}} service. Distance: {{distance}}{{distance_unit}}. Fare: {{fare_amount}}.\",\"fr\":\"Bonjour {{driver_name}}, on vous a assigné la course #{{ride_number}}. Allez chercher {{rider_name}} ({{rider_phone}}) pour le service {{service_category}}. Distance : {{distance}}{{distance_unit}}. Tarif : {{fare_amount}}.\",\"de\":\"Hallo {{driver_name}}, Ihnen wurde Fahrt #{{ride_number}} zugewiesen. Holen Sie {{rider_name}} ({{rider_phone}}) für den Service {{service_category}} ab. Entfernung: {{distance}}{{distance_unit}}. Fahrpreis: {{fare_amount}}.\",\"ar\":\"مرحباً {{driver_name}}، تم تعيينك لرحلة رقم #{{ride_number}}. التقاط {{rider_name}} ({{rider_phone}}) لخدمة {{service_category}}. المسافة: {{distance}}{{distance_unit}}. الأجرة: {{fare_amount}}.\"}', '{\"en\":\"/driver/ride/{{ride_id}}\",\"fr\":\"/driver/ride/{{ride_id}}\",\"de\":\"/driver/ride/{{ride_id}}\",\"ar\":\"/driver/ride/{{ride_id}}\"}', NULL, '2025-06-01 12:45:36', '2025-06-01 12:45:36'),
(4, '{\"en\":\"Withdrawal Request Update\",\"fr\":\"Mise à jour de la demande de retrait\",\"de\":\"Auszahlungsanfrage-Update\",\"ar\":\"تحديث طلب السحب\"}', 'update-withdraw-request-driver', '{\"en\":\"Hello {{driver_name}}, your withdrawal request of {{amount}} has been updated. Current status: {{status}}.\",\"fr\":\"Bonjour {{driver_name}}, votre demande de retrait de {{amount}} a été mise à jour. Statut actuel : {{status}}.\",\"de\":\"Hallo {{driver_name}}, Ihre Auszahlungsanfrage über {{amount}} wurde aktualisiert. Aktueller Status: {{status}}.\",\"ar\":\"مرحباً {{driver_name}}، تم تحديث طلب السحب الخاص بك بقيمة {{amount}}. الحالة الحالية: {{status}}.\"}', '{\"en\":\"/driver/wallet\",\"fr\":\"/driver/wallet\",\"de\":\"/driver/wallet\",\"ar\":\"/driver/wallet\"}', NULL, '2025-06-01 13:19:31', '2025-06-01 13:19:41'),
(5, '{\"en\":\"Bid Status Update\",\"fr\":\"Mise à jour du statut de loffre\",\"de\":\"Gebotsstatus-Update\",\"ar\":\"تحديث حالة المزايدة\"}', 'bid-status-driver', '{\"en\":\"Hello {{driver_name}}, your bid for Ride #{{ride_number}} with {{rider_name}} has been {{bid_status}}.\",\"fr\":\"Bonjour {{driver_name}}, votre offre pour la course #{{ride_number}} avec {{rider_name}} a été {{bid_status}}.\",\"de\":\"Hallo {{driver_name}}, Ihr Gebot für Fahrt #{{ride_number}} mit {{rider_name}} wurde {{bid_status}}.\",\"ar\":\"مرحباً {{driver_name}}، تم {{bid_status}} مزايدتك على الرحلة رقم #{{ride_number}} مع {{rider_name}}.\"}', '{\"en\":\"/driver/bids\",\"fr\":\"/driver/bids\",\"de\":\"/driver/bids\",\"ar\":\"/driver/bids\"}', NULL, '2025-06-01 13:22:15', '2025-06-01 13:22:15'),
(6, '{\"en\":\"Document Status Update\",\"fr\":\"Mise à jour du statut du document\",\"de\":\"Dokumentstatus-Update\",\"ar\":\"تحديث حالة المستند\"}', 'driver-document-status-update', '{\"en\":\"Hello {{driver_name}}, your document \"{{document_name}}\" has been {{status}}. Please check your profile for details.\",\"fr\":\"Bonjour {{driver_name}}, votre document \"{{document_name}}\" a été {{status}}. Veuillez vérifier votre profil pour plus de détails.\",\"de\":\"Hallo {{driver_name}}, Ihr Dokument \"{{document_name}}\" wurde {{status}}. Bitte überprüfen Sie Ihr Profil für Details.\",\"ar\":\"مرحباً {{driver_name}}، تم {{status}} المستند \"{{document_name}}\". يرجى التحقق من ملفك الشخصي للحصول على التفاصيل.\"}', '{\"en\":\"/driver/documents\",\"fr\":\"/driver/documents\",\"de\":\"/driver/documents\",\"ar\":\"/driver/documents\"}', NULL, '2025-06-01 13:25:07', '2025-06-01 13:25:07'),
(7, '{\"en\":\"New Withdrawal Request\",\"fr\":\"Nouvelle demande de retrait\",\"de\":\"Neue Auszahlungsanfrage\",\"ar\":\"طلب سحب جديد\"}', 'create-withdraw-request-admin', '{\"en\":\"New withdrawal request: {{driver_name}} has requested {{amount}}. Please review in admin panel.\",\"fr\":\"Nouvelle demande de retrait : {{driver_name}} a demandé {{amount}}. Veuillez examiner dans le panneau d administration.\",\"de\":\"Neue Auszahlungsanfrage: {{driver_name}} hat {{amount}} beantragt. Bitte im Admin-Bereich überprüfen.\",\"ar\":\"طلب سحب جديد: {{driver_name}} طلب {{amount}}. يرجى المراجعة في لوحة الإدارة.\"}', '{\"en\":\"/admin/withdrawals\",\"fr\":\"/admin/withdrawals\",\"de\":\"/admin/withdrawals\",\"ar\":\"/admin/withdrawals\"}', NULL, '2025-06-01 13:26:48', '2025-06-01 13:26:48');

