INSERT INTO `testimonials` (`id`, `title`, `description`, `rating`, `status`, `profile_image_id`, `created_by_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '{\"en\":\"Sarah Johnson\",\"fr\":\"Sarah Johnson\",\"de\":\"Sarah Johnson\",\"ar\":\"Sarah Johnson\"}', '{\"en\":\"The intercity ride was incredibly comfortable and punctual. The driver was professional, and the car was spotless. I highly recommend this service for long-distance travel!\",\"fr\":\"Le trajet interurbain était incroyablement confortable et ponctuel. Le chauffeur était professionnel et la voiture était impeccable. Je recommande vivement ce service pour les voyages longue distance !\",\"de\":\"Die Intercity-Fahrt war unglaublich bequem und pünktlich. Der Fahrer war professionell und das Auto war makellos. Ich kann diesen Service für Langstreckenfahrten nur empfehlen!\",\"ar\":\"كانت الرحلة بين المدن مريحة للغاية وفي الموعد المحدد. كان السائق محترفاً والسيارة نظيفة تماماً. أوصي بشدة بهذه الخدمة للسفر لمسافات طويلة!\"}', 4, 1, 1196, 1, '2025-01-23 05:21:29', '2025-12-25 07:48:06', NULL),
(4, '{\"en\":\"Emily Davis\",\"fr\":\"Emily Davis\",\"de\":\"Emily Davis\",\"ar\":\"Emily Davis\"}', '{\"en\":\"I needed to send an urgent package, and the service was fantastic. The delivery was fast, and the tracking system kept me updated every step of the way.\",\"fr\":\"J avais besoin d envoyer un colis urgent, et le service était fantastique. La livraison a été rapide, et le système de suivi m a tenu informé à chaque étape.\",\"de\":\"Ich musste ein dringendes Paket verschicken, und der Service war fantastisch. Die Lieferung war schnell, und das Tracking-System hielt mich auf dem Laufenden.\",\"ar\":\"كنت بحاجة إلى إرسال طرد عاجل، وكانت الخدمة رائعة. كان التسليم سريعاً، وظل نظام التتبع يطلعني على كل خطوة.\"}', 4, 1, 1194, 1, '2025-01-23 05:25:51', '2025-12-25 07:47:56', NULL),
(5, '{\"en\":\"Olivia Martinez\",\"fr\":\"Olivia Martinez\",\"de\":\"Olivia Martinez\",\"ar\":\"Olivia Martinez\"}', '{\"en\":\"Renting a car for our weekend getaway was seamless. The vehicle was in excellent condition, and the pickup/drop-off process was super convenient.\",\"fr\":\"Louer une voiture pour notre escapade de week-end a été simple. Le véhicule était en excellent état, et le processus de prise en charge et de restitution était très pratique.\",\"de\":\"Das Mieten eines Autos für unser Wochenendausflug war problemlos. Das Fahrzeug war in ausgezeichnetem Zustand, und der Abhol- und Rückgabeprozess war sehr bequem.\",\"ar\":\"كان تأجير سيارة لعطلة نهاية الأسبوع سلاسة. كانت السيارة في حالة ممتازة، وكانت عملية الاستلام والتسليم مريحة للغاية.\"}', 5, 1, 1186, 1, '2025-01-23 05:26:25', '2025-12-25 07:47:41', NULL),
(7, '{\"en\":\"Sophia Lee\",\"fr\":\"Sophia Lee\",\"de\":\"Sophia Lee\",\"ar\":\"Sophia Lee\"}', '{\"en\":\"I have been using the cab service for months, and it has always been a great experience. The drivers are courteous, and the cars are always clean.\",\"fr\":\"J utilise le service de taxi depuis des mois, et c est toujours une excellente expérience. Les chauffeurs sont courtois et les voitures sont toujours propres.\",\"de\":\"Ich nutze den Taxi-Service seit Monaten, und es war immer eine großartige Erfahrung. Die Fahrer sind höflich und die Autos sind immer sauber.\",\"ar\":\"كنت أستخدم خدمة سيارات الأجرة منذ أشهر، وكانت دائماً تجربة رائعة. السائقون مهذبون والسيارات دائماً نظيفة.\"}', 5, 1, 1188, 1, '2025-01-23 05:27:45', '2025-12-25 07:47:32', NULL),
(9, '{\"en\":\"Ava Rodriguez\",\"fr\":\"Ava Rodriguez\",\"de\":\"Ava Rodriguez\",\"ar\":\"Ava Rodriguez\"}', '{\"en\":\"I booked a scheduled ride for a meeting, and it was flawless. The driver was professional, and the car was luxurious. I will definitely use this service again!\",\"fr\":\"J ai réservé un trajet programmé pour une réunion, et c était impeccable. Le chauffeur était professionnel et la voiture était luxueuse. Je vais certainement réutiliser ce service !\",\"de\":\"Ich habe eine geplante Fahrt für ein Meeting gebucht, und es war makellos. Der Fahrer war professionell und das Auto war luxuriös. Ich werde diesen Service definitiv wieder nutzen!\",\"ar\":\"حجزت رحلة مجدولة لاجتماع، وكانت لا تشوبها شائبة. كان السائق محترفاً والسيارة فاخرة. سأستخدم هذه الخدمة مرة أخرى بالتأكيد!\"}', 5, 1, 1178, 1, '2025-01-23 05:28:50', '2025-12-25 07:47:20', NULL);

